// src/Component/UserList.js
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchUsersAsync,
  createUserAsync,
  updateUserAsync,
  deleteUserAsync,
  selectUsersState,
} from "./userSlice";
import "./UserList.css";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  const [editUserId, setEditUserId] = useState(null);
  const [editData, setEditData] = useState({});
  const [showAddForm, setShowAddForm] = useState(false);
  const [newUserData, setNewUserData] = useState({
    username: "",
    email: "",
    first_name: "",
    last_name: "",
    is_active: true,
    profile: { bio: "", phone: "" },
  });

  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 5;

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  // Handle edit
  const handleEditClick = (user) => {
    setEditUserId(user.id);
    setEditData({ ...user });
  };

  const handleChange = (key, value, isNew = false) => {
    if (isNew) {
      if (key === "bio" || key === "phone") {
        setNewUserData({
          ...newUserData,
          profile: { ...newUserData.profile, [key]: value },
        });
      } else if (key === "is_active") {
        setNewUserData({ ...newUserData, [key]: value });
      } else {
        setNewUserData({ ...newUserData, [key]: value });
      }
    } else {
      if (key === "bio" || key === "phone") {
        setEditData({
          ...editData,
          profile: { ...editData.profile, [key]: value },
        });
      } else if (key === "is_active") {
        setEditData({ ...editData, [key]: value });
      } else {
        setEditData({ ...editData, [key]: value });
      }
    }
  };

  // Save edited user
  const handleSave = async () => {
    if (!editUserId) return;
    try {
      await dispatch(updateUserAsync(editData)).unwrap();
      setEditUserId(null);
      dispatch(fetchUsersAsync());
      alert("✅ User updated successfully");
    } catch (err) {
      console.error(err);
      alert("Update failed");
    }
  };

  // Delete user
  const handleDelete = async (id) => {
    if (!id) return;
    if (window.confirm("Are you sure you want to delete this user?")) {
      try {
        await dispatch(deleteUserAsync(id)).unwrap();
        dispatch(fetchUsersAsync());
        alert("User deleted successfully");
      } catch (err) {
        console.error(err);
        alert("Delete failed");
      }
    }
  };

  // Create new user
  const handleAddUser = async (e) => {
    e.preventDefault();
    try {
      await dispatch(createUserAsync(newUserData)).unwrap();
      setNewUserData({
        username: "",
        email: "",
        first_name: "",
        last_name: "",
        is_active: true,
        profile: { bio: "", phone: "" },
      });
      setShowAddForm(false);
      dispatch(fetchUsersAsync());
      alert("✅ User added successfully");
    } catch (err) {
      console.error(err);
      alert("Failed to add user");
    }
  };

  // Pagination
  const indexOfLastUser = currentPage * usersPerPage;
  const indexOfFirstUser = indexOfLastUser - usersPerPage;
  const currentUsers = users.slice(indexOfFirstUser, indexOfLastUser);
  const totalPages = Math.ceil(users.length / usersPerPage);

  return (
    <div className="userlist-container">
      <h2>User Management</h2>

      {/* Add User Toggle Button */}
      <button
        className="add-user-btn"
        onClick={() => setShowAddForm(!showAddForm)}
      >
        {showAddForm ? "Close Add User Form" : "Add New User"}
      </button>

      {/* Add User Form */}
      {showAddForm && (
        <form onSubmit={handleAddUser} className="add-user-form">
          <input
            type="text"
            placeholder="Username"
            value={newUserData.username}
            onChange={(e) => handleChange("username", e.target.value, true)}
            required
          />
          <input
            type="email"
            placeholder="Email"
            value={newUserData.email}
            onChange={(e) => handleChange("email", e.target.value, true)}
            required
          />
          <input
            type="text"
            placeholder="First Name"
            value={newUserData.first_name}
            onChange={(e) => handleChange("first_name", e.target.value, true)}
          />
          <input
            type="text"
            placeholder="Last Name"
            value={newUserData.last_name}
            onChange={(e) => handleChange("last_name", e.target.value, true)}
          />
          <input
            type="text"
            placeholder="Bio"
            value={newUserData.profile.bio}
            onChange={(e) => handleChange("bio", e.target.value, true)}
          />
          <input
            type="text"
            placeholder="Phone"
            value={newUserData.profile.phone}
            onChange={(e) => handleChange("phone", e.target.value, true)}
          />
          <select
            value={newUserData.is_active ? "Active" : "Inactive"}
            onChange={(e) =>
              handleChange("is_active", e.target.value === "Active", true)
            }
          >
            <option>Active</option>
            <option>Inactive</option>
          </select>
          <button type="submit" className="add-user-submit-btn">
            Add User
          </button>
        </form>
      )}

      {loading && <p>Loading users...</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}

      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Username</th>
            <th>Email</th>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Bio</th>
            <th>Phone</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {currentUsers.length > 0 ? (
            currentUsers.map((u) => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.username || ""}
                      onChange={(e) => handleChange("username", e.target.value)}
                    />
                  ) : (
                    u.username
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="email"
                      value={editData.email || ""}
                      onChange={(e) => handleChange("email", e.target.value)}
                    />
                  ) : (
                    u.email
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.first_name || ""}
                      onChange={(e) => handleChange("first_name", e.target.value)}
                    />
                  ) : (
                    u.first_name
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.last_name || ""}
                      onChange={(e) => handleChange("last_name", e.target.value)}
                    />
                  ) : (
                    u.last_name
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.profile?.bio || ""}
                      onChange={(e) => handleChange("bio", e.target.value)}
                    />
                  ) : (
                    u.profile?.bio || ""
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.profile?.phone || ""}
                      onChange={(e) => handleChange("phone", e.target.value)}
                    />
                  ) : (
                    u.profile?.phone || ""
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <select
                      value={editData.is_active ? "Active" : "Inactive"}
                      onChange={(e) =>
                        handleChange("is_active", e.target.value === "Active")
                      }
                    >
                      <option>Active</option>
                      <option>Inactive</option>
                    </select>
                  ) : u.is_active ? (
                    "Active"
                  ) : (
                    "Inactive"
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <div style={{ display: "flex", gap: "5px" }}>
                      <button className="save-btn" onClick={handleSave}>
                        Save
                      </button>
                      <button
                        className="cancel-btn"
                        onClick={() => setEditUserId(null)}
                      >
                        Cancel
                      </button>
                    </div>
                  ) : (
                    <div style={{ display: "flex", gap: "5px" }}>
                      <button
                        className="edit-btn"
                        onClick={() => handleEditClick(u)}
                      >
                        Edit
                      </button>
                      <button
                        className="delete-btn"
                        onClick={() => handleDelete(u.id)}
                      >
                        Delete
                      </button>
                    </div>
                  )}
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="9" style={{ textAlign: "center" }}>
                No users found
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Pagination Controls */}
      {totalPages > 1 && (
        <div style={{ marginTop: "10px" }}>
          {Array.from({ length: totalPages }, (_, i) => (
            <button
              key={i + 1}
              onClick={() => setCurrentPage(i + 1)}
              style={{
                marginRight: "5px",
                padding: "5px 10px",
                backgroundColor: currentPage === i + 1 ? "#1f48ff" : "#ccc",
                color: currentPage === i + 1 ? "#fff" : "#000",
                border: "none",
                borderRadius: "4px",
                cursor: "pointer",
              }}
            >
              {i + 1}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export default UserList;
